/**
 * Bundle the AudioWorklet wrappers + their pure cores into classic
 * scripts under public/.
 *
 * Why generated files: `vite dev` transforms TS on demand but
 * `vite build` ships ?url-imported TS raw — the classic
 * addAudioWorkletModule() path would parse-error only in production.
 * Bundling to checked-in public/*.worklet.js makes dev and build serve
 * the IDENTICAL artifact. Re-run after editing envelopeCore,
 * thresholdCore, or a wrapper:  npm run build:worklets
 */

import { build } from 'esbuild';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

const entries = [
  ['src/audio/worklets/envelope.worklet.ts', 'public/envelope.worklet.js'],
  ['src/audio/worklets/threshold.worklet.ts', 'public/threshold.worklet.js'],
  [
    'src/audio/worklets/pluckedString.worklet.ts',
    'public/pluckedString.worklet.js',
  ],
  [
    'src/audio/worklets/struckString.worklet.ts',
    'public/struckString.worklet.js',
  ],
  ['src/audio/worklets/bowedString.worklet.ts', 'public/bowedString.worklet.js'],
  ['src/audio/worklets/modalBody.worklet.ts', 'public/modalBody.worklet.js'],
  ['src/audio/worklets/fdnReverb.worklet.ts', 'public/fdnReverb.worklet.js'],
  ['src/audio/worklets/flute.worklet.ts', 'public/flute.worklet.js'],
];

mkdirSync(resolve(root, 'public'), { recursive: true });

for (const [entry, outfile] of entries) {
  await build({
    entryPoints: [resolve(root, entry)],
    outfile: resolve(root, outfile),
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: 'es2020',
    banner: {
      js: '// GENERATED by scripts/build-worklets.mjs — edit the sources under src/audio/worklets/ and the cores, then re-run. Do not hand-edit.',
    },
  });
  console.log(`built ${outfile}`);
}
